/**
 * Media registry: maps each section to its processed assets in /public/media.
 * Populated in Phase 2 from media-map.md (generated by `npm run media`).
 */

export type VideoAsset = {
  id: string;
  /** e.g. /media/hero-1920.mp4 */
  mp4: { w1920: string; w1080: string };
  webm: { w1920: string; w1080: string };
  poster: string;
  /** tiny blurred placeholder (data URI or small file) */
  placeholder: string;
  focus: "left" | "center" | "right";
};

export type ImageAsset = {
  id: string;
  /** base path without width/extension, e.g. /media/img/trek */
  base: string;
  widths: readonly number[];
  alt: string;
};

export const videos: Record<string, VideoAsset> = {};
export const images: Record<string, ImageAsset> = {};
